import {node,card,empty,fmt} from './chunk-F51FD76F14331921.js';
import {sparkline} from './chunk-693D1C0782FE7255.js';
const NS='http://www.w3.org/2000/svg';function svgEl(tag,attrs={},text){const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!=null)n.textContent=text;return n;}
/** One chart per metric. No interpolation of missing evaluation checkpoints. */
export function chart({title,key,points,selected,maxStep,yMax,kind='line',color='var(--chart-gold)',onSelect,foot='',legend=''}){const box=card('s-chart');const head=node('div','s-chart-head');head.append(node('strong','',title),node('span','s-chart-legend',legend|| (kind==='dots'?'● Checkpoint 评测':'— 原始记录')));box.append(head,node('div','s-metric-key',key||'未记录'));
 const valid=points.filter(p=>typeof p.value==='number'&&Number.isFinite(p.value));if(!valid.length){box.append(empty('尚未记录此指标'));box.append(node('small','s-chart-foot',foot));return box;}
 const w=480,h=202,left=50,right=25,top=20,bottom=32;const xmax=Math.max(1,maxStep??0,...points.map(p=>p.step));let ymin=yMax!=null?0:Math.min(...valid.map(p=>p.value)),ymax=yMax!=null?yMax:Math.max(...valid.map(p=>p.value));if(ymin===ymax){ymin-=.1;ymax+=.1;}else if(yMax==null){let pad=(ymax-ymin)*.12;ymin-=pad;ymax+=pad;}const x=v=>left+v/xmax*(w-left-right),y=v=>top+(ymax-v)/(ymax-ymin)*(h-top-bottom);const svg=svgEl('svg',{viewBox:`0 0 ${w} ${h}`,role:'img','aria-label':title,class:'s-chart-svg'});
 for(let i=0;i<4;i++){const val=ymin+(ymax-ymin)*i/3;svg.append(svgEl('line',{x1:left,y1:y(val),x2:w-right,y2:y(val),stroke:'var(--chart-grid)'}),svgEl('text',{x:left-8,y:y(val)+4,'text-anchor':'end',class:'s-axis'},fmt(val,yMax?0:2)));}
 for(let i=0;i<5;i++){const v=xmax*i/4;svg.append(svgEl('line',{x1:x(v),y1:top,x2:x(v),y2:h-bottom,stroke:'var(--chart-grid-soft)'}),svgEl('text',{x:x(v),y:h-10,'text-anchor':'middle',class:'s-axis'},fmt(v,0)));}
 if(kind==='dots'){for(const p of valid){const c=svgEl('circle',{cx:x(p.step),cy:y(p.value),r:5,fill:color,tabindex:0,role:'button','aria-label':`选择 step ${p.step} ${p.label||p.value}`});const cb=()=>onSelect?.(p.step,p);c.onclick=cb;c.onkeydown=e=>{if(e.key==='Enter')cb();};const t=svgEl('title',{},p.label||String(p.value));c.append(t);svg.append(c,svgEl('text',{x:x(p.step),y:y(p.value)-12,'text-anchor':'middle',class:'s-point-label'},p.label||p.value));}}
 else{let segment=[];const draw=()=>{if(!segment.length)return;if(segment.length===1){const p=segment[0];svg.append(svgEl('circle',{cx:x(p.step),cy:y(p.value),r:2,fill:color}));}else{const layer=svgEl('svg',{width:w,height:h,'stroke-width':2,stroke:color,'stroke-linecap':'round','stroke-linejoin':'round',overflow:'visible'});sparkline(layer,segment,{interactive:false,xMap:p=>x(p.step),yMap:p=>y(p.value)});layer.querySelector('.sparkline--fill')?.remove();svg.append(layer);}segment=[];};for(const p of points){if(typeof p.value!=='number'||!Number.isFinite(p.value)){draw();continue;}segment.push(p);}draw();}
 if(selected!=null)svg.append(svgEl('line',{x1:x(selected),x2:x(selected),y1:top-5,y2:h-bottom,stroke:'var(--chart-mint)','stroke-dasharray':'5 4','stroke-width':1.5}));
 svg.addEventListener('click',e=>{if(e.target.tagName==='circle'||!onSelect)return;const rect=svg.getBoundingClientRect();const step=Math.max(0,Math.min(xmax,((e.clientX-rect.left)/rect.width*w-left)/(w-left-right)*xmax));const p=valid.reduce((a,b)=>Math.abs(a.step-step)<Math.abs(b.step-step)?a:b);onSelect(p.step,p);});box.append(svg,node('div','s-chart-foot',foot+'　 ·　训练 step'));return box;}
